/**
 * Regenerates api/_lib/export/templateFiles.generated.ts from the real files under each
 * template family's own directory (src/templates/corporate/, src/templates/restaurant/,
 * ...). The export endpoint ships these file CONTENTS verbatim inside every exported
 * project's ZIP — this script is what keeps that bundled copy in sync with the actual
 * template source, without the API handler ever needing runtime filesystem access to
 * files outside its own import graph (which isn't reliably available once deployed as a
 * Vercel serverless function). See the generated file's header comment and README.md's
 * "Template families" section for the full rationale.
 *
 * Run automatically via the `predev`/`pretest`/`prebuild` npm scripts; the output is
 * also committed to git so a plain `npm ci && npm run build` (or running tests without
 * `npm run dev` first) always has an up-to-date copy regardless of script ordering.
 *
 * Adding a third family means adding one entry to FAMILIES below — nothing else in this
 * script changes.
 */
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'

const TEMPLATES_ROOT = path.resolve(import.meta.dirname, '..', 'src', 'templates')
const OUTPUT_FILE = path.resolve(import.meta.dirname, '..', 'api', '_lib', 'export', 'templateFiles.generated.ts')

const INCLUDED_EXTENSIONS = new Set(['.ts', '.tsx', '.css'])

// Factory-only or dev-only pieces that a standalone exported site has no use for —
// see README.md's "Template families" section for what each is for.
const EXCLUDED_DIR_NAMES = new Set(['__tests__', 'sample-data'])
const EXCLUDED_FILENAMES = new Set(['registry.ts', 'registry.tsx', 'index.ts'])

interface FamilyManifest {
  /** Directory name under src/templates/ this family's source lives in. */
  dirName: string
  /** Exported constant name in the generated output file. */
  exportName: string
}

const FAMILIES: FamilyManifest[] = [
  { dirName: 'corporate', exportName: 'CORPORATE_TEMPLATE_FILES' },
  { dirName: 'restaurant', exportName: 'RESTAURANT_TEMPLATE_FILES' },
  { dirName: 'real-estate', exportName: 'REAL_ESTATE_TEMPLATE_FILES' },
  { dirName: 'portfolio', exportName: 'PORTFOLIO_TEMPLATE_FILES' },
  { dirName: 'catalog', exportName: 'CATALOG_TEMPLATE_FILES' },
  { dirName: 'ecommerce', exportName: 'ECOMMERCE_TEMPLATE_FILES' },
]

function collectFiles(dir: string, relativeTo: string): string[] {
  const entries = readdirSync(dir)
  const results: string[] = []

  for (const entry of entries) {
    if (EXCLUDED_DIR_NAMES.has(entry)) continue
    const fullPath = path.join(dir, entry)
    const stat = statSync(fullPath)

    if (stat.isDirectory()) {
      results.push(...collectFiles(fullPath, relativeTo))
      continue
    }

    if (entry.endsWith('.test.ts') || entry.endsWith('.test.tsx')) continue
    if (EXCLUDED_FILENAMES.has(entry)) continue
    if (!INCLUDED_EXTENSIONS.has(path.extname(entry))) continue

    results.push(path.relative(relativeTo, fullPath).split(path.sep).join('/'))
  }

  return results
}

function buildManifestEntries(family: FamilyManifest): { exportName: string; relativePaths: string[]; entries: string[] } {
  const sourceRoot = path.join(TEMPLATES_ROOT, family.dirName)
  const relativePaths = collectFiles(sourceRoot, sourceRoot).sort()

  if (relativePaths.length === 0) {
    throw new Error(`No template files found under ${sourceRoot} — refusing to write an empty manifest.`)
  }

  const entries = relativePaths.map((relativePath) => {
    const content = readFileSync(path.join(sourceRoot, relativePath), 'utf8')
    return `  ${JSON.stringify(relativePath)}: ${JSON.stringify(content)},`
  })

  return { exportName: family.exportName, relativePaths, entries }
}

function main() {
  const manifests = FAMILIES.map(buildManifestEntries)

  const blocks = manifests.map(
    ({ exportName, entries }) =>
      `/** Keyed by path relative to that family's directory under src/templates/, using forward slashes. */\nexport const ${exportName}: Record<string, string> = {\n${entries.join('\n')}\n}\n`,
  )

  const output = `// AUTO-GENERATED by scripts/buildExportManifest.ts — do not edit by hand.
// Regenerate with: npx tsx scripts/buildExportManifest.ts
// (also runs automatically via the predev/pretest/prebuild npm scripts)
//
// Verbatim contents of each template family's src/templates/<family>/**, minus
// factory-only/dev-only files (tests, sample-data, registry.ts(x), index.ts). Bundled as
// plain string constants so the exported-site ZIP builder (api/_lib/export/) never needs
// runtime filesystem access to files outside its own import graph — see that script's
// header comment for why.

${blocks.join('\n')}`

  writeFileSync(OUTPUT_FILE, output, 'utf8')
  for (const { exportName, relativePaths } of manifests) {
    console.log(`Wrote ${relativePaths.length} files to ${exportName} (${path.relative(process.cwd(), OUTPUT_FILE)})`)
  }
}

main()
